// Shared glue for the Pagefind Component UI, used by SearchModal (header) and
// the /search fallback page. The bundle lives in /pagefind/*, generated by
// scripts/pagefind-index.mjs at build time and served from build/pagefind in
// dev/preview by the servePagefind vite plugin (by the static host in prod).

let ready: Promise<void> | null = null;

/** Inject the Component UI css + module once (client-only; call from onMount).
   Loaded via injected tags to bypass Vite's module resolution of a path that
   only exists after `pnpm build`. Rejects if the bundle is missing (fresh
   checkout before the first build) — callers degrade to inert markup. */
export function loadPagefindUI(): Promise<void> {
	if (!ready) {
		const css = document.createElement('link');
		css.rel = 'stylesheet';
		css.href = '/pagefind/pagefind-component-ui.css';
		document.head.appendChild(css);

		ready = new Promise((resolve, reject) => {
			const script = document.createElement('script');
			script.type = 'module';
			script.src = '/pagefind/pagefind-component-ui.js';
			script.onload = () => resolve();
			script.onerror = () => reject(new Error('Pagefind bundle missing — run `pnpm build` once'));
			document.head.appendChild(script);
		});
	}
	return ready;
}

/** Result template for <pagefind-results> (rendered via {@html}, since Svelte
   would parse the {{ }} moustaches as expressions). Adapted from the built-in
   template — keeps the pf-* classes so Pagefind's own stylesheet still applies —
   plus a type badge from the `type` metadata that scripts/pagefind-index.mjs
   stamps on every page. The badge class must NOT start with `pf-`: Pagefind's
   stylesheet force-reverts every [class^="pf-"] element, wiping custom styles. */
export const RESULT_TEMPLATE = `<script type="text/pagefind-template">
	<li class="pf-result">
		<div class="pf-result-card">
			<div class="pf-result-content">
				<p class="pf-result-title">
					{{#if meta.type}}<span class="type-badge" data-type="{{ meta.type }}">{{ meta.type }}</span>{{/if}}
					<a class="pf-result-link" href="{{ meta.url | default(url) | safeUrl }}">{{ meta.title | default("Untitled") }}</a>
				</p>
				{{#if excerpt}}
				<p class="pf-result-excerpt">{{+ excerpt +}}</p>
				{{/if}}
			</div>
		</div>
		{{#if sub_results}}
		<ul class="pf-heading-chips">
			{{#each sub_results as sub}}
			<li class="pf-heading-chip">
				<a class="pf-heading-link" href="{{ sub.url | safeUrl }}">{{ sub.title | default("Section") }}</a>
				<p class="pf-heading-excerpt">{{+ sub.excerpt +}}</p>
			</li>
			{{/each}}
		</ul>
		{{/if}}
	</li>
<\/script>`;
